<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';
interface Menu { id:number; key:string; parent_id:number|null; module_id:number|null; label:string; route:string|null; icon:string; permission:string|null; sort_order:number; is_visible:boolean; developer_only:boolean; is_system:boolean }
interface Module { id:number; name:string }
const items=ref<Menu[]>([]);const modules=ref<Module[]>([]);const loading=ref(false);const saving=ref(false);const error=ref('');const message=ref('');
const form=ref({key:'',label:'',route:'',icon:'circle',permission:'',module_id:'',parent_id:'',sort_order:0,is_visible:true,developer_only:false});
function csrf():string{const row=document.cookie.split('; ').find(v=>v.startsWith('XSRF-TOKEN='));return row?decodeURIComponent(row.slice(11)):'';}
function headers():Record<string,string>{return{Accept:'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest','X-XSRF-TOKEN':csrf()};}
async function load():Promise<void>{loading.value=true;error.value='';try{const [m,n]=await Promise.all([fetch('/api/v1/backend/menu-registry',{credentials:'same-origin',headers:headers()}),fetch('/api/v1/backend/modules',{credentials:'same-origin',headers:headers()})]);if(!m.ok||!n.ok)throw new Error('Unable to load menu registry.');items.value=(await m.json()).data??[];modules.value=(await n.json()).data??[];}catch(e){error.value=e instanceof Error?e.message:'Unable to load menus.';}finally{loading.value=false;}}
async function create():Promise<void>{saving.value=true;error.value='';message.value='';try{const response=await fetch('/api/v1/backend/menu-registry',{method:'POST',credentials:'same-origin',headers:headers(),body:JSON.stringify({...form.value,route:form.value.route||null,permission:form.value.permission||null,module_id:form.value.module_id?Number(form.value.module_id):null,parent_id:form.value.parent_id?Number(form.value.parent_id):null})});const data=await response.json();if(!response.ok)throw new Error(data.message??'Unable to create menu item.');form.value={key:'',label:'',route:'',icon:'circle',permission:'',module_id:'',parent_id:'',sort_order:0,is_visible:true,developer_only:false};message.value='Menu item created.';await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to create menu item.';}finally{saving.value=false;}}
async function remove(item:Menu):Promise<void>{if(item.is_system||!window.confirm(`Delete menu item ${item.label}?`))return;try{const response=await fetch(`/api/v1/backend/menu-registry/${item.id}`,{method:'DELETE',credentials:'same-origin',headers:headers()});const data=await response.json();if(!response.ok)throw new Error(data.message??'Unable to delete menu item.');message.value=`${item.label} deleted.`;await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to delete menu item.';}}
async function save(item:Menu):Promise<void>{error.value='';try{const payload:Record<string,unknown>={key:item.key,label:item.label,icon:item.icon,permission:item.permission,is_visible:item.is_visible,sort_order:item.sort_order};if(!item.is_system){payload.route=item.route;payload.parent_id=item.parent_id;payload.module_id=item.module_id;payload.developer_only=item.developer_only;}const response=await fetch(`/api/v1/backend/menu-registry/${item.id}`,{method:'PUT',credentials:'same-origin',headers:headers(),body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.message??'Unable to save menu item.');message.value=`${item.label} saved.`;}catch(e){error.value=e instanceof Error?e.message:'Unable to save menu item.';await load();}}
onMounted(()=>{void load();});
</script>
<template><Head title="Menu Registry"/><ErpLayout><div class="space-y-5 p-4 md:p-6"><header class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Developer Controls</p><h1 class="text-2xl font-semibold">Menu Registry</h1><p class="mt-1 text-sm text-muted-foreground">Database-managed sidebar navigation. Visibility never replaces backend authorization.</p></div><button class="rounded-lg border px-3 py-2 text-sm" @click="load">Refresh</button></header><p v-if="message" class="rounded-lg border border-emerald-300 bg-emerald-50 p-3 text-sm text-emerald-800">{{message}}</p><p v-if="error" class="rounded-lg border border-red-300 bg-red-50 p-3 text-sm text-red-700">{{error}}</p><section class="rounded-xl border bg-card p-4"><h2 class="font-semibold">Add custom menu item</h2><form class="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3" @submit.prevent="create"><label class="text-sm">Stable key<input v-model="form.key" required pattern="[a-z0-9]+([._-][a-z0-9]+)*" maxlength="150" placeholder="custom.menu-item" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="text-sm">Label<input v-model="form.label" required maxlength="120" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="text-sm">Route<input v-model="form.route" placeholder="/custom/page" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="text-sm">Icon<input v-model="form.icon" maxlength="80" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="text-sm">Permission slug<input v-model="form.permission" placeholder="system.module.view" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="text-sm">Parent menu<select v-model="form.parent_id" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"><option value="">Top-level</option><option v-for="item in items.filter(i=>!i.parent_id)" :key="item.id" :value="String(item.id)">{{item.label}}</option></select></label><label class="text-sm">Module<select v-model="form.module_id" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"><option value="">No module</option><option v-for="module in modules" :key="module.id" :value="String(module.id)">{{module.name}}</option></select></label><label class="text-sm">Sort order<input v-model.number="form.sort_order" type="number" min="0" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="flex items-center gap-2 pt-6 text-sm"><input v-model="form.is_visible" type="checkbox"/> Visible</label><label class="flex items-center gap-2 pt-6 text-sm"><input v-model="form.developer_only" type="checkbox"/> Developer only</label><div><button :disabled="saving" class="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">{{saving?'Saving…':'Create menu item'}}</button></div></form></section><section class="overflow-hidden rounded-xl border bg-card"><div class="border-b p-4"><h2 class="font-semibold">Registered navigation items</h2><p class="text-xs text-muted-foreground">System entries keep their route and parent structure; label, icon, permission, order and visibility can be managed.</p></div><div v-if="loading" class="p-6 text-sm text-muted-foreground">Loading…</div><div v-else class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-muted/50 text-xs uppercase text-muted-foreground"><tr><th class="p-3">Menu</th><th class="p-3">Route</th><th class="p-3">Permission</th><th class="p-3">Visible</th><th class="p-3">Order</th><th class="p-3">Action</th></tr></thead><tbody><tr v-for="item in items" :key="item.id" class="border-t"><td class="p-3"><input v-model="item.label" class="w-44 rounded border bg-background px-2 py-1"/><input v-model="item.icon" class="mt-1 w-44 rounded border bg-background px-2 py-1" aria-label="Menu icon"/><div class="mt-1 text-xs text-muted-foreground">{{item.key}} · {{item.is_system?'System':'Custom'}} · {{item.parent_id?'Child':'Root'}} · {{item.icon}}</div></td><td class="p-3 text-xs">{{item.route??'—'}}</td><td class="p-3"><input v-model="item.permission" class="w-52 rounded border bg-background px-2 py-1" placeholder="No permission"/></td><td class="p-3"><input v-model="item.is_visible" type="checkbox" aria-label="Visible"/></td><td class="p-3"><input v-model.number="item.sort_order" type="number" min="0" class="w-20 rounded border bg-background px-2 py-1"/></td><td class="p-3"><div class="flex gap-2"><button class="rounded-lg border px-3 py-1.5 text-xs" @click="save(item)">Save</button><button v-if="!item.is_system" class="rounded-lg border border-red-300 px-3 py-1.5 text-xs text-red-700" @click="remove(item)">Delete</button></div></td></tr></tbody></table></div></section></div></ErpLayout></template>
